18	\subsection{Transformer vs. RNN：优势对比}
19	
20	\begin{table}[H]
21	\centering
22	\caption{RNN 与 Transformer 的对比}
23	\begin{tabular}{lcc}
24	\toprule
25	\textbf{特性} & \textbf{RNN/LSTM} & \textbf{Transformer} \\
26	\midrule
27	处理方式 & 逐时间步（Sequential） & 全序列并行（Parallel） \\
28	长期依赖 & 困难（梯度消失） & 直接建模（Self-Attention） \\
29	训练效率 & 低（无法并行化） & 高（可充分利用 GPU） \\
30	位置信息 & 隐式（通过时间步顺序） & 显式（Positional Encoding） \\
31	可扩展性 & 有限 & 强（支持超大规模） \\
32	\bottomrule
33	\end{tabular}
34	\end{table}
